#!/usr/bin/env node
// Writes the docs site's reference pages from the source they describe: the
// keyboard shortcuts, the CLI's help and the MCP tools agents get. `--check`
// fails when a page is out of date instead of writing it.

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";

import { emit } from "./lib/generated.mjs";

const root = resolve(import.meta.dirname, "..");
const out = resolve(root, "docs-site/src/content/docs/reference");
const banner =
  "{/* Generated by scripts/generate-docs-reference.mjs. Do not edit by hand. */}";

const emitPage = (name, contents) => emit(resolve(out, name), contents);

const page = (title, description, body) =>
  `---\ntitle: ${JSON.stringify(title)}\ndescription: ${JSON.stringify(description)}\n---\n\n${banner}\n\n${body.trim()}\n`;

const cell = (text) =>
  String(text ?? "")
    .replaceAll("|", "\\|")
    .replaceAll("\n", " ")
    .replace(/[{}<]/g, (char) => `\\${char}`);

// The app's default shortcuts, from the table GPUI's keymap reads, labelled as a Mac shows them.
const keybindings = JSON.parse(
  await readFile(
    resolve(root, "crates/sikemux-core/src/assets/keybindings.json"),
    "utf8",
  ),
);
const CATEGORIES = ["Workspace", "Agents", "Panes", "Navigation", "Browser"];
const MODIFIERS = { Meta: "⌘", Ctrl: "⌃", Alt: "⌥", Shift: "⇧" };
const KEYS = {
  Backquote: "`",
  Backslash: "\\",
  BracketLeft: "[",
  BracketRight: "]",
  Comma: ",",
  Enter: "↵",
  Equal: "=",
  Escape: "Esc",
  Minus: "-",
  Period: ".",
  Quote: "'",
  Semicolon: ";",
  Slash: "/",
};
const label = (keys) => {
  const parts = keys.split("+");
  const code = parts.pop();
  const key = KEYS[code] ?? code.replace(/^(Key|Digit|Arrow)/, "");
  return parts.map((part) => MODIFIERS[part] ?? part).join("") + key;
};

const shortcuts = CATEGORIES.map((category) => {
  const rows = keybindings
    .filter((action) => action.category === category && action.mac)
    .map(
      (action) =>
        `| ${cell(action.label)} | \`${label(action.mac)}\` | ${cell(action.detail)} |`,
    );
  if (rows.length === 0) return "";
  return `## ${category}\n\n| Action | Shortcut | What it does |\n|---|---|---|\n${rows.join("\n")}\n`;
})
  .filter(Boolean)
  .join("\n");
await emitPage(
  "keyboard-shortcuts.mdx",
  page(
    "Keyboard shortcuts",
    "Every default shortcut in Sikemux on a Mac.",
    `These are the defaults. Change any of them in **Settings → Keyboard**, and search every action with the command deck (\`⌘⇧P\`).\n\n${shortcuts}`,
  ),
);

const cliSource = await readFile(
  resolve(root, "crates/sikemux-host/src/cli_client/mod.rs"),
  "utf8",
);
const help = cliSource.match(/const HELP: &str = r#"([\s\S]*?)"#;/)?.[1];
if (!help)
  throw new Error(
    "could not find the CLI help in crates/sikemux-host/src/cli_client/mod.rs",
  );
await emitPage(
  "cli.mdx",
  page(
    "CLI",
    "The sikemux command: run this host's core, open files and projects, call Sikemux's tools.",
    `On a Mac, install the \`sikemux\` command from **Settings → Command line**. On a server it comes with the core. \`sikemux help <command>\` explains each one.\n\n\`\`\`text\n${help}\`\`\``,
  ),
);

const { tools, families = [] } = JSON.parse(
  await readFile(resolve(root, "tools/tools.json"), "utf8"),
);
const groups = new Map();
for (const tool of tools) {
  const prefix = tool.name.split("_")[0];
  const family = families.find(({ name }) => name === prefix);
  const named = family
    ? `${family.name} ${tool.name.slice(prefix.length + 1)}`
    : tool.name;
  if (!groups.has(prefix)) groups.set(prefix, []);
  groups.get(prefix).push(`| \`${named}\` | ${cell(tool.description)} |`);
}
const toolSections = [...groups]
  .map(
    ([prefix, rows]) =>
      `## ${prefix}\n\n| Tool | What it does |\n|---|---|\n${rows.join("\n")}\n`,
  )
  .join("\n");
await emitPage(
  "mcp-tools.mdx",
  page(
    "MCP tools",
    "The sikemux-tools MCP tools every agent in Sikemux gets.",
    `Every agent Sikemux starts gets these tools through the \`sikemux-tools\` MCP server. The same calls work from a terminal with \`sikemux tool METHOD [JSON_PARAMS]\`.${families.length > 0 ? ` A tool listed with an action, such as \`browser navigate\`, is one tool, \`browser\`, called with \`action: "navigate"\`.` : ""}\n\n${toolSections}`,
  ),
);

console.log(
  `✓ docs reference: ${keybindings.length} actions, ${tools.length} tools`,
);
